Aight, lemme break it down real quick an show ya code you can run. Idea simple:

- Map every name to an id and build an adjacency set for each user.
- For each user x, walk through x's friends f, then walk f's friends y. If y ain't x and ain't already a friend of x, increment cnt[y].
- After that, among all y that ain't x and ain't friends with x, find the max cnt value and count how many y reach that max. If there ain't any such y (x friends everybody), result is 0.

This gives correct counts even when the max is 0 (means all non-friends tie with 0 common friends).

Python 3 implementation (read from stdin, print to stdout):

import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m = int(data[0])
    idx = 1

    name_to_id = {}
    names = []
    edges = []

    for _ in range(m):
        a = data[idx]; b = data[idx+1]; idx += 2
        for s in (a, b):
            if s not in name_to_id:
                name_to_id[s] = len(names)
                names.append(s)
        u = name_to_id[a]
        v = name_to_id[b]
        edges.append((u, v))

    n = len(names)
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    res = [0] * n

    for x in range(n):
        cnt = [0] * n
        # bump counts for non-friends reachable via a common friend
        for f in adj[x]:
            for y in adj[f]:
                if y == x or y in adj[x]:
                    continue
                cnt[y] += 1

        maxv = -1
        c = 0
        for y in range(n):
            if y == x or y in adj[x]:
                continue
            if cnt[y] > maxv:
                maxv = cnt[y]
                c = 1
            elif cnt[y] == maxv:
                c += 1

        if maxv == -1:
            res[x] = 0
        else:
            res[x] = c

    out = []
    out.append(str(n))
    for i, name in enumerate(names):
        out.append(f"{name} {res[i]}")

    sys.stdout.write("\n".join(out))

if __name__ == '__main__':
    main()

